INSERT INTO public.quiz_questions (id, module_id, kind, prompt, options, correct, explanation, source, critical) VALUES
  ('app_honest_found', 'app', 'single', 'Після походу ви нічого не знайшли, але натиснули «Так, знайшли», щоб отримати бали. Що станеться насправді?', '[{"id": "a", "text": "Нічого: бали за відгук усе одно не нараховуються"}, {"id": "b", "text": "Бали нарахуються, а статистика «Прогноз для вас збувся» і дані для налаштування прогнозу вашої області стануть неправдивими"}, {"id": "c", "text": "Застосунок одразу помітить обман і заблокує акаунт"}, {"id": "d", "text": "Це вплине лише на інших грибників, а не на вас"}]'::jsonb, '["b"]'::jsonb, 'Відгуки «Знайшли» рахують, як часто прогноз справджується саме для вас, і накопичуються (з вагою довіри до ваших відповідей) для налаштування прогнозу вашої області. Хибне «Так» псує і те, і інше — обман обертається проти вас. Бали за відгук нараховуються через добу, тож обман «спрацює», але шкодить саме вам.', 'ADR-014 §14.1–14.2; B3.11 (міграція 20261126140000_trip_feedback)', false),
  ('app_honest_notfound', 'app', 'single', 'Вранці ви поставили точку з фото білого гриба, а ввечері на питання «Знайшли гриби?» відповіли «Ні», щоб «не світити» місце. Як це сприйме сервер?', '[{"id": "a", "text": "Ніяк — відгук і точки ніяк не пов''язані"}, {"id": "b", "text": "Як суперечність: довіра до ваших відгуків знизиться, балів за цей відгук не буде"}, {"id": "c", "text": "Точку автоматично видалять"}, {"id": "d", "text": "Покаже ваше місце іншим, щоб перевірити"}]'::jsonb, '["b"]'::jsonb, 'Сервер порівнює «Ні» з вашими ж точками з фото того дня поруч. Якщо вони є — це суперечність: довіра до відгуків падає, бали за відгук не нараховуються. Місце при цьому нікому не показується, а відгук «Ні» і так не розкриває місць — приховувати нічого не треба.', 'ADR-014 §14.2 (довіра feedback_trust); міграція 20261126140000_trip_feedback', false),
  ('app_notfound_calibration', 'app', 'single', 'Чому відповідь «Ні, не знайшли» не використовується для налаштування прогнозу області, а «Так, знайшли» — використовується?', '[{"id": "a", "text": "Бо «Ні» дають лише ті, хто не вміє шукати"}, {"id": "b", "text": "Бо «Ні» нічого не доводить: гриби могли рости за 200 м від того місця, де ви шукали"}, {"id": "c", "text": "Бо «Ні» не потрібне — прогноз завжди правий"}, {"id": "d", "text": "Бо за «Ні» не дають балів"}]'::jsonb, '["b"]'::jsonb, 'Знахідка доводить, що гриби були. Відсутність знахідки — ні: людина могла пройти повз поляну. Тому «Ні» лишається для вашої особистої статистики, але не тягне прогноз області вниз.', 'ADR-019 §19.9', false),
  ('app_feedback_no_place', 'app', 'single', 'Щоб спитати «Знайшли?», застосунок передає на сервер середину треку походу. Що сервер робить з цим місцем?', '[{"id": "a", "text": "Зберігає назавжди, щоб будувати карту ваших улюблених місць"}, {"id": "b", "text": "Показує друзям"}, {"id": "c", "text": "Лише перевіряє, чи похід був біля вашої ділянки прогнозу або з Наглядачем, і не зберігає"}, {"id": "d", "text": "Передає в прогноз іншим грибникам"}]'::jsonb, '["c"]'::jsonb, 'Місце потрібне лише для перевірки, що відгук стосується справжнього походу (≤ 5 км від ділянки прогнозу чи трек походу з Наглядачем). Саме місце не зберігається.', 'B3.11 (v1-analysis/feedback; міграція 20261126140000)', false),
  ('app_feedback_no_context', 'app', 'single', 'Ви сходили в ліс за 30 км від своєї ділянки прогнозу, без Наглядача, і натиснули «Я вдома». Питання «Знайшли?» не з''явилось. Чому?', '[{"id": "a", "text": "Збій застосунку"}, {"id": "b", "text": "Сервер не бачить зв''язку походу з прогнозом, який ви отримували, — тож відповідь не мала б сенсу для точності прогнозу"}, {"id": "c", "text": "Питання з''являється лише раз на тиждень"}, {"id": "d", "text": "У вас низький рівень"}]'::jsonb, '["b"]'::jsonb, 'Відгук приймається лише для конкретного походу: біля ділянки, прогноз якої ви отримали на цей день, або з Наглядачем. Інакше ні перевірити, ні використати відповідь неможливо — і застосунок не питає даремно.', 'ADR-014 §14.2; B3.11', false),
  ('app_fuzz_stable', 'app', 'single', 'Публічну точку іншим показано зі зсувом 300–500 м. Хтось відкриває її сто разів, щоб «усереднити» зсув і знайти справжнє місце. Що вийде?', '[{"id": "a", "text": "Справжнє місце: середнє сотні випадкових зсувів — у центрі"}, {"id": "b", "text": "Нічого: зсув для кожної точки постійний — сто разів покажеться те саме місце"}, {"id": "c", "text": "Застосунок покаже справжнє місце після десятого відкриття"}, {"id": "d", "text": "Точка зникне"}]'::jsonb, '["b"]'::jsonb, 'Зсув стабільний: для точки він обчислюється один раз із секретного ключа на сервері. Тому повторні запити завжди показують те саме зсунуте місце — усереднювати нічого.', 'ADR-018 §18.5; supabase/functions/_shared/picks/fuzz.ts', false),
  ('app_fuzz_why', 'app', 'single', 'Навіщо публічну точку показують зі зсувом, якщо автор сам вирішив поділитися?', '[{"id": "a", "text": "Щоб місце не витоптали й не вибрали дочиста, а грибник показав район, а не конкретний пень"}, {"id": "b", "text": "Через помилку GPS"}, {"id": "c", "text": "Щоб точки не накладались на карті"}, {"id": "d", "text": "Щоб більше людей купили Pro"}]'::jsonb, '["a"]'::jsonb, 'Публічна точка каже «тут ліс плодоносить», але не веде натовп до одного пня. Справжнє місце бачить лише автор.', 'ADR-018 §18.5', false),
  ('app_confirm_far', 'app', 'single', 'Ви бачите на карті чужу сіру публічну точку білого гриба, приходите рівно на позначку й знаходите там білий. Чи підтвердить ваша знахідка цю точку?', '[{"id": "a", "text": "Так, завжди — ви ж на позначці"}, {"id": "b", "text": "Не обов''язково: позначка зсунута на 300–500 м, а зараховується знахідка до 200 м від справжнього місця"}, {"id": "c", "text": "Ні, підтверджувати можуть лише модератори"}, {"id": "d", "text": "Так, якщо сфотографуєте позначку на екрані"}]'::jsonb, '["b"]'::jsonb, 'Іншим видно зсунуте місце, а підтвердження рахується від справжнього — до 200 м. Тому підтвердити може лише той, хто справді знайшов гриби поруч зі знахідкою автора. Якщо не зараховано, ваша знахідка лишається вашою звичайною публічною точкою.', 'ADR-019 §19.5; B3.8 (міграція 20261126150000_pick_confirmations)', false),
  ('app_confirm_attempts', 'app', 'single', 'Чому на одну чужу точку дається лише дві спроби підтвердити, і кожна витрачає ваш тижневий ліміт публічних точок?', '[{"id": "a", "text": "Щоб ніхто не перебором координат не вирахував справжнє місце точки"}, {"id": "b", "text": "Щоб економити місце на сервері"}, {"id": "c", "text": "Бо більше двох людей не можуть підтверджувати одну точку"}, {"id": "d", "text": "Щоб частіше купували Pro"}]'::jsonb, '["a"]'::jsonb, 'Якби сервер необмежено відповідав «ближче чи далі 200 м», справжнє місце можна було б знайти перебором. Дві спроби, кожна з реальною публічною точкою і фото, роблять це неможливим.', 'B3.8a (міграція 20261126150000_pick_confirmations)', false),
  ('app_confirm_species', 'app', 'single', 'Біля чужої точки «Лисичка» ви знайшли білий гриб і відповіли знахідкою. Чи підтвердить це точку?', '[{"id": "a", "text": "Так — місце ж плодоносить"}, {"id": "b", "text": "Ні: підтверджують знахідкою того самого виду — інакше вид точки ніхто не перевірив"}, {"id": "c", "text": "Так, якщо білий більший"}, {"id": "d", "text": "Так, але бали не нарахують"}]'::jsonb, '["b"]'::jsonb, 'Підтвердження перевіряє саме вид: інша людина незалежно знайшла той самий гриб у тому ж місці. Знахідка іншого виду про це нічого не каже.', 'B3.8a (can_confirm_pick: species_mismatch)', false),
  ('app_confirm_twin', 'app', 'single', 'Телефон автора під час зйомки помітив схожість із отруйним двійником. Скільки незалежних підтверджень потрібно, щоб точка стала «Підтвердженою»?', '[{"id": "a", "text": "Одне, як завжди"}, {"id": "b", "text": "Два — і попередження про двійника лишається навіть на зеленій точці"}, {"id": "c", "text": "Жодного: така точка підтверджується автоматично"}, {"id": "d", "text": "Така точка ніколи не стане зеленою і зникає"}]'::jsonb, '["b"]'::jsonb, 'Де є ризик отруйного двійника, однієї людини мало: потрібні дві незалежні знахідки, а попередження в картці не знімається.', 'ADR-019 §19.5 п.6; міграція 20261126150000_pick_confirmations', false),
  ('app_mock_location', 'app', 'single', 'Програма підміни GPS показує, що ви біля чужої точки, хоча ви вдома. Ви фотографуєте старий гриб з холодильника і відповідаєте знахідкою. Що буде?', '[{"id": "a", "text": "Точку буде підтверджено"}, {"id": "b", "text": "Підтвердження не зарахують: телефон повідомляє про підмінене місце, а місце фото має збігатися з точкою"}, {"id": "c", "text": "Застосунок не дасть відкрити камеру"}, {"id": "d", "text": "Ви отримаєте подвійні бали"}]'::jsonb, '["b"]'::jsonb, 'Android повідомляє, коли місце підмінене програмою, — така відповідь не зараховується. Додатково сервер перевіряє, що місце й час зйомки з даних фото збігаються з точкою. Підтвердження зараховується лише тоді, коли телефон прямо сказав, що місце справжнє.', 'B3.8b (міграція 20261126160000_confirm_mock_location); ADR-019 §19.5', false),
  ('app_photo_camera', 'app', 'single', 'Чому тук-тук можна створити лише фото з камери застосунку, без галереї?', '[{"id": "a", "text": "Щоб точка була там і тоді, де й коли гриб справді знайшли, — фото з галереї могло бути зроблене будь-де"}, {"id": "b", "text": "Бо галерея повільна"}, {"id": "c", "text": "Щоб фото були однакового розміру"}, {"id": "d", "text": "Через авторські права"}]'::jsonb, '["a"]'::jsonb, 'Точка — це свідчення «тут і зараз». Фото з камери застосунку разом із місцем і часом зйомки підтверджує, що знахідка справжня.', 'ADR-018 §18.3', false),
  ('app_exif_removed', 'app', 'single', 'У фото з телефона записані координати й час зйомки. Що з ними робить сервер, коли ви публікуєте точку?', '[{"id": "a", "text": "Показує іншим разом із фото"}, {"id": "b", "text": "Перевіряє, що фото зроблене поруч і нещодавно, а потім вирізає ці дані з фото"}, {"id": "c", "text": "Нічого не робить"}, {"id": "d", "text": "Надсилає в Google"}]'::jsonb, '["b"]'::jsonb, 'Дані з фото (EXIF) потрібні лише для перевірки, що знахідка справжня. Після перевірки сервер їх вирізає, інакше точне місце можна було б дістати з фото публічної точки.', 'ADR-002; supabase/functions/_shared/picks/exif.ts', false),
  ('app_ai_local', 'app', 'single', 'Ви розпізнаєте гриб у глухому лісі без зв''язку. Що відбувається з фото?', '[{"id": "a", "text": "Розпізнавання не працює без інтернету"}, {"id": "b", "text": "Модель працює прямо на телефоні — фото нікуди не надсилається"}, {"id": "c", "text": "Фото чекає на зв''язок і йде на сервер"}, {"id": "d", "text": "Фото надсилається через SMS"}]'::jsonb, '["b"]'::jsonb, 'Розпізнавання — лише на телефоні (локальна модель), без серверних запитів і лімітів. Тому працює й без зв''язку, якщо модель завантажена.', 'ADR-006', false),
  ('app_ai_verdict', 'app', 'single', 'ШІ показав «Ймовірно: опеньок осінній». Що з цього правильно?', '[{"id": "a", "text": "Можна їсти — ШІ рідко помиляється"}, {"id": "b", "text": "Це підказка для пошуку в довіднику; рішення «їсти чи ні» ШІ не ухвалює"}, {"id": "c", "text": "Якщо ймовірність висока — можна не перевіряти двійників"}, {"id": "d", "text": "Гриб занесено в прогноз"}]'::jsonb, '["b"]'::jsonb, 'Розпізнавання — лише підказка: з якого виду почати перевірку в довіднику й на кого з двійників звернути увагу. У опенька є небезпечні двійники, і фото не передає всіх ознак.', 'ADR-006; екран розпізнавання (рівні без відсотків)', false),
  ('app_forecast_poison', 'app', 'single', 'Прогноз ділянки показує «що зараз росте». Чи може там з''явитися бліда поганка?', '[{"id": "a", "text": "Так, якщо для неї ідеальна погода"}, {"id": "b", "text": "Ні: прогноз показує лише їстівні й умовно їстівні види — про отруйні є довідник і розділ безпеки"}, {"id": "c", "text": "Так, але сірим кольором"}, {"id": "d", "text": "Лише у Pro"}]'::jsonb, '["b"]'::jsonb, 'Отруйні види ніколи не потрапляють у прогноз — це закріплено фільтром за довідником. Але те, що їх немає в прогнозі, не означає, що їх немає в лісі.', 'B2.4 (supabase/functions/_shared/forecast/db.ts)', false),
  ('app_forecast_not_in_forecast', 'app', 'single', 'Прогноз показує «маслюк — висока ймовірність». У лісі ви знайшли гриб, схожий на маслюк. Що з цього випливає?', '[{"id": "a", "text": "Це маслюк — прогноз його підтвердив"}, {"id": "b", "text": "Нічого про цей конкретний гриб: прогноз каже про шанс виду в лісі, а не про те, що саме ви знайшли"}, {"id": "c", "text": "Отруйних схожих зараз немає — їх же немає в прогнозі"}, {"id": "d", "text": "Можна їсти без перевірки"}]'::jsonb, '["b"]'::jsonb, 'Прогноз — про ймовірність появи виду, а не визначник. Отруйні двійники ростуть у ті самі хвилі, просто прогноз їх не показує. Кожен гриб перевіряйте за ознаками.', 'B2.4; ADR-015', false),
  ('app_forecast_inputs', 'app', 'multi', 'Що враховує прогноз ділянки? Оберіть усе правильне.', '[{"id": "a", "text": "Дощі й температуру за попередні дні"}, {"id": "b", "text": "Тип лісу й дерева на ділянці"}, {"id": "c", "text": "Сезон і хвилі плодоношення виду"}, {"id": "d", "text": "Фаза Місяця"}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Рушій зважує погоду з запізненням (дощ і тепло за попередні дні), ліс ділянки (які дерева — з ними гриби в союзі) і сезон/хвилі виду. Місяць у розрахунок не входить.', 'ADR-015; supabase/functions/_shared/forecast/', false),
  ('app_forecast_horizon', 'app', 'single', 'Чому прогноз на 6–7-й день позначено «орієнтовно»?', '[{"id": "a", "text": "Бо на далекі дні погоду прогнозують менш точно, а прогноз грибів залежить від погоди"}, {"id": "b", "text": "Бо гриби на 7-й день завжди погані"}, {"id": "c", "text": "Бо ці дні лише для Pro"}, {"id": "d", "text": "Через помилку в застосунку"}]'::jsonb, '["a"]'::jsonb, 'Прогноз грибів стоїть на прогнозі погоди. Що далі день, то більший розкид погоди — і тим менш певний прогноз грибів.', 'ADR-015; analysis.ts (approximate_label)', false),
  ('app_crowd_verified', 'app', 'single', 'За останній тиждень біля вашої ділянки троє грибників знайшли білий гриб, і їхні знахідки підтвердили інші. Як це вплине на прогноз білого на вашій ділянці?', '[{"id": "a", "text": "Ніяк: прогноз рахується лише з погоди"}, {"id": "b", "text": "Рівень прогнозу підніметься на один щабель — справжні знахідки сильніші за розрахунок"}, {"id": "c", "text": "Прогноз одразу стане «пік», навіть у посуху"}, {"id": "d", "text": "Прогноз знизиться, бо там уже все зібрали"}]'::jsonb, '["b"]'::jsonb, 'Рушій враховує підтверджені знахідки того самого виду в радіусі 10 км за 7 днів: три й більше — рівень на щабель вище. Відсутність знахідок прогноз не знижує (більшість лісів ніхто не відвідує), а з «немає даних» знахідки рівень не піднімають — «пік» із нуля не зроблять. Тому чесні точки й підтвердження — внесок і у ваш прогноз.', 'supabase/functions/_shared/forecast/crowd.ts; ADR-019 §19.5', false),
  ('app_no_picks_no_penalty', 'app', 'single', 'Біля вашої ділянки за тиждень ніхто не поставив жодної точки. Що з цього робить прогноз?', '[{"id": "a", "text": "Знижує рівень: раз ніхто не знайшов — грибів немає"}, {"id": "b", "text": "Нічого не змінює: те, що ніхто не відзначив знахідок, не означає, що грибів немає"}, {"id": "c", "text": "Ставить «немає даних» для всіх видів"}, {"id": "d", "text": "Підвищує рівень — гриби ніхто не зібрав"}]'::jsonb, '["b"]'::jsonb, 'Більшість лісів ніхто з користувачів не відвідує щотижня, тож «немає точок» — це відсутність даних, а не доказ, що грибів немає. Прогноз тоді рахується з погоди, лісу й сезону. Так само «не знайшов» не тягне прогноз униз.', 'supabase/functions/_shared/forecast/crowd.ts; ADR-019 §19.9', false),
  ('app_region_only', 'app', 'single', 'Чому ділянку прогнозу можна створити лише у своїй області?', '[{"id": "a", "text": "Бо в інших областях немає лісів"}, {"id": "b", "text": "Безкоштовний прогноз — для вашої області; так застосунок може тримати для неї докладні дані лісів, і їх не можна використовувати по всій країні з одного акаунта"}, {"id": "c", "text": "Через закон про персональні дані"}, {"id": "d", "text": "Бо GPS працює лише в межах області"}]'::jsonb, '["b"]'::jsonb, 'Усе в застосунку прив''язано до вашої домашньої області: ліси, карта без інтернету, ділянки. Змінити область — лише один раз протягом доби після вибору, далі — за правилами Pro або через підтримку.', 'ADR-015 §15.2; ADR-016', false),
  ('app_levels_points', 'app', 'single', 'Новачок пройшов усі тести і має 120 балів, але не створював точок. Який у нього рівень?', '[{"id": "a", "text": "Лісовик"}, {"id": "b", "text": "Грибознавець: сертифікат знань і понад 51 бал, але до Лісовика (201) потрібна справжня активність у лісі"}, {"id": "c", "text": "Грибний Майстер"}, {"id": "d", "text": "Мандрівник — тести не дають рівня"}]'::jsonb, '["b"]'::jsonb, 'Тести дають до 120 балів і сертифікат — це рівень Грибознавця. Вищі рівні — лише за реальну активність: точки, підтвердження, чесні відгуки.', 'ADR-013 §13.1; ADR-023 §23.4', false),
  ('app_master_needs_cert', 'app', 'single', 'Грибник набрав 1500 балів точками й підтвердженнями, але тестів не проходив. Хто він?', '[{"id": "a", "text": "Грибний Майстер"}, {"id": "b", "text": "Хранитель лісу: Майстром без сертифіката знань не стати — Майстер має знати отруйних двійників"}, {"id": "c", "text": "Лісовик"}, {"id": "d", "text": "Грибознавець"}]'::jsonb, '["b"]'::jsonb, 'Найвищий рівень вимагає і балів, і сертифіката знань. Без сертифіката грибник із будь-якою кількістю балів лишається Хранителем лісу.', 'ADR-013 §13.1', false),
  ('app_public_level', 'app', 'single', 'Чому публічні точки можна ставити лише з рівня «Лісовик»?', '[{"id": "a", "text": "Щоб на спільній карті були знахідки людей, які вже довели, що впевнено визначають гриби"}, {"id": "b", "text": "Бо новачки не мають камери"}, {"id": "c", "text": "Щоб карта була порожньою"}, {"id": "d", "text": "Через ліміти сервера"}]'::jsonb, '["a"]'::jsonb, 'Публічну точку бачать усі в області, і хтось може піти за нею в ліс. Тому ділитися можуть ті, хто вже має досвід, а новачки ставлять приватні точки для себе.', 'ADR-013; ADR-019 §19.10', false),
  ('app_guest', 'app', 'multi', 'Ви користуєтеся застосунком як гість, без входу. Що вам доступно? Оберіть усе правильне.', '[{"id": "a", "text": "Прогноз ділянки і карта"}, {"id": "b", "text": "Розпізнавання й довідник"}, {"id": "c", "text": "SOS, компас, «Додому» й поради з безпеки"}, {"id": "d", "text": "Публічні точки, друзі й Наглядач"}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Гість має прогноз, карту, приватні точки, розпізнавання, довідник і всю безпеку, що не потребує його даних на сервері. Публічні точки, друзі, Наглядач, бали й рівні — після входу.', 'ADR-001 (уточнення PO 2026-11-17)', false),
  ('app_guardian_sees', 'app', 'single', 'Ви пішли в ліс із Наглядачем і натиснули «Я вдома». Що Наглядач бачить після цього?', '[{"id": "a", "text": "Увесь ваш трек назавжди"}, {"id": "b", "text": "Нічого: похід завершено, трек на сервері видаляється"}, {"id": "c", "text": "Лише кінцеву точку"}, {"id": "d", "text": "Ваші точки з грибами"}]'::jsonb, '["b"]'::jsonb, 'Наглядач бачить вас лише під час походу — щоб допомогти, якщо щось трапиться. Після «Я вдома» трек на сервері стирається.', 'ADR-022; міграція 20261120110000_guardian_in_app', false),
  ('app_guardian_why_friends', 'app', 'single', 'Чому Наглядачем може бути лише друг у застосунку, а не будь-хто за посиланням?', '[{"id": "a", "text": "Посилання може потрапити до чужих людей, а ваше місце в лісі — чутлива інформація"}, {"id": "b", "text": "Бо посилання платні"}, {"id": "c", "text": "Щоб у застосунку було більше користувачів"}, {"id": "d", "text": "Бо в лісі не працюють посилання"}]'::jsonb, '["a"]'::jsonb, 'Посилання легко переслати. Наглядач — це людина, якій ви довіряєте й яку додали в друзі; ваше місце бачить лише вона й лише під час походу.', 'ADR-022', false),
  ('app_offline_order', 'app', 'order', 'Ви їдете в ліс, де немає зв''язку. Розставте дії в правильному порядку.', '[{"id": "a", "text": "Удома, з інтернетом: завантажити офлайн-карту області, стежки й модель ШІ"}, {"id": "b", "text": "Перед виходом: побудувати маршрут від машини й почати похід"}, {"id": "c", "text": "У лісі: повертатися за треком або «Додому», навіть без зв''язку"}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Без зв''язку застосунок працює лише з тим, що вже на телефоні. Карту, стежки й модель потрібно завантажити заздалегідь, а маршрут — почати до того, як зникне зв''язок.', 'ADR-020; вкладка «Безпека» (похід, «Додому»)', false),
  ('app_private_limit', 'app', 'single', 'Чому приватних точок одночасно може бути лише кілька (без Pro — 5)?', '[{"id": "a", "text": "Бо фото займають місце на сервері, а приватні точки — це закладки «повернутися сюди», а не архів"}, {"id": "b", "text": "Щоб ніхто не знав про ваші місця"}, {"id": "c", "text": "Бо більше 5 місць не буває"}, {"id": "d", "text": "Через закон"}]'::jsonb, '["a"]'::jsonb, 'Дорого коштують не рядки, а фото: тисячі людей щодня — це сотні гігабайтів. Тому ліміт — на кількість одночасно: видаліть стару, щоб додати нову.', 'ADR-019 §19.10', false),
  ('app_delete_data', 'app', 'single', 'Ви видалили акаунт у «Налаштуваннях». Що стається з вашими даними?', '[{"id": "a", "text": "Лишаються на сервері «про всяк випадок»"}, {"id": "b", "text": "Видаляються профіль, нік, точки, ділянки, рейтинг — відновити неможливо"}, {"id": "c", "text": "Видаляється лише профіль, точки лишаються іншим"}, {"id": "d", "text": "Акаунт лише ховається на 30 днів"}]'::jsonb, '["b"]'::jsonb, 'Видалення акаунта стирає ваші дані каскадом. Копію своїх даних можна попросити в підтримки, доки акаунт існує.', 'DELETE v1-me (B6.2); B6.1 (копія на запит)', false),
  ('app_why_honesty_overall', 'app', 'multi', 'Що з цього допомагає прогнозу бути точнішим? Оберіть усе правильне.', '[{"id": "a", "text": "Чесні відповіді «Знайшли?» після походу"}, {"id": "b", "text": "Точки з фото там, де ви справді знайшли гриби, — особливо підтверджені іншими"}, {"id": "c", "text": "Відповідати «Так» щоразу, щоб отримати бали"}, {"id": "d", "text": "Не відповідати взагалі — прогноз і так знає все"}]'::jsonb, '["a", "b"]'::jsonb, 'Підтверджені знахідки того самого виду поруч за тиждень піднімають рівень прогнозу ділянки. Чесні відгуки «Знайшли?» рахують, як часто прогноз справджується для вас, і накопичуються для налаштування прогнозу області. Хибні «Так» псують ці дані, а мовчання нічого не дає.', 'ADR-014 §14.1; supabase/functions/_shared/forecast/crowd.ts', false)
