-- ============================================================================
-- Тести знань: модуль «Як працює Грибний Радар» (app) — ADR-023
-- ============================================================================
-- Згенеровано scripts/quiz/build_module.py з data/quiz/app.json; читабельна версія — docs/quiz/app.md.
-- Питання оновлюються (за id), прибрані з JSON — знімаються з публікації; модуль публікується.

ON CONFLICT (id) DO UPDATE SET
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, correct = EXCLUDED.correct,
  explanation = EXCLUDED.explanation, source = EXCLUDED.source, critical = EXCLUDED.critical,
  published = true, hidden_by_reports = false, updated_at = now();

UPDATE public.quiz_questions SET published = false, updated_at = now()
WHERE module_id = 'app' AND id NOT IN ('app_honest_found', 'app_honest_notfound', 'app_notfound_calibration', 'app_feedback_no_place', 'app_feedback_no_context', 'app_fuzz_stable', 'app_fuzz_why', 'app_confirm_far', 'app_confirm_attempts', 'app_confirm_species', 'app_confirm_twin', 'app_mock_location', 'app_photo_camera', 'app_exif_removed', 'app_ai_local', 'app_ai_verdict', 'app_forecast_poison', 'app_forecast_not_in_forecast', 'app_forecast_inputs', 'app_forecast_horizon', 'app_crowd_verified', 'app_no_picks_no_penalty', 'app_region_only', 'app_levels_points', 'app_master_needs_cert', 'app_public_level', 'app_guest', 'app_guardian_sees', 'app_guardian_why_friends', 'app_offline_order', 'app_private_limit', 'app_delete_data', 'app_why_honesty_overall');

UPDATE public.quiz_modules SET published = true WHERE id = 'app';
